INSERT INTO biology_sources(version,id,title,url,design,population,limitation) VALUES ('biology-2026-10-18.1','wholefood-2023','Host-diet-gut microbiome interactions influence human energy balance: a randomized clinical trial','https://www.nature.com/articles/s41467-023-38778-x','Controlled whole-diet crossover study; 17 participants','Population and applicability must be checked in the linked source; not assumed to match you.','Whole-diet intervention in a small cohort; does not establish effects or doses for any individual recipe ingredient.'),('biology-2026-10-18.1','walnut-2024','Correlation between intestinal microbiota and urolithin metabolism in a human walnut dietary intervention','https://pubmed.ncbi.nlm.nih.gov/39548408/','Three-week human walnut dietary intervention','Population and applicability must be checked in the linked source; not assumed to match you.','Metabolite production depends on metabotype; microbiome associations do not establish a longevity benefit or a universal response.'),('biology-2026-10-18.1','fiber-2024','Investigating the response of the butyrate production potential to major fibers in dietary intervention studies','https://www.nature.com/articles/s41522-024-00533-5','Pooled reanalysis of 14 human fiber intervention datasets','Population and applicability must be checked in the linked source; not assumed to match you.','Inferred pathways are not measured butyrate flux. Different fibers and studies were pooled; the findings do not establish exact effects of whole-food servings.'),('biology-2026-10-18.1','resistant-starch-2012','Ruminococcus bromii is a keystone species for the degradation of resistant starch in the human colon','https://www.nature.com/articles/ismej20124','Human-derived bacterial cultures and community experiments','Population and applicability must be checked in the linked source; not assumed to match you.','Mechanistic experiments do not establish a clinical benefit or a reliable way to acquire a missing organism by eating a particular food.'),('biology-2026-10-18.1','fermented-2021','Gut-microbiota-targeted diets modulate human immune status','https://pubmed.ncbi.nlm.nih.gov/34256014/','17-week randomized prospective study; 18 participants per diet arm','Population and applicability must be checked in the linked source; not assumed to match you.','Small study of generally healthy adults. Benefits were not attributed to a single strain, and eating a fermented food does not guarantee durable colonization.'),('biology-2026-10-18.1','athletes-2019','Meta-omics analysis of elite athletes identifies a performance-enhancing microbe that functions via lactate metabolism','https://pubmed.ncbi.nlm.nih.gov/31235964/','Human athlete observations plus mechanistic mouse experiments','Population and applicability must be checked in the linked source; not assumed to match you.','This is not proof that feeding or supplementing Veillonella improves performance in humans. Exercise-derived lactate is not a dietary substrate prescription.'),('biology-2026-10-18.1','centenarians-2021','Novel bile acid biosynthetic pathways are enriched in the microbiome of centenarians','https://pubmed.ncbi.nlm.nih.gov/34325466/','Japanese centenarian cohort plus bacterial culture experiments','Population and applicability must be checked in the linked source; not assumed to match you.','Association with exceptional age does not establish causation. No diet shown here makes a person live longer or reproduces that cohort microbiome.'),('biology-2026-10-18.1','pnpla3-study','Romeo et al. 2008 — PNPLA3 and hepatic fat','https://www.nature.com/articles/ng.257','Human genetic association','Population and applicability must be checked in the linked source; not assumed to match you.','Association with liver fat does not diagnose disease or validate a genotype-specific diet or supplement.'),('biology-2026-10-18.1','tm6sf2-study','Kozlitina et al. 2014 — TM6SF2 and liver fat','https://www.nature.com/articles/ng.2901','Human genetic association with functional experiments','Population and applicability must be checked in the linked source; not assumed to match you.','Liver and circulating lipid effects can differ. No genotype-specific food prescription is established here.'),('biology-2026-10-18.1','gckr-study','Orho-Melander et al. 2008 — GCKR, triglycerides and fasting glucose','https://pubmed.ncbi.nlm.nih.gov/18678614/','Human genetic association','Population and applicability must be checked in the linked source; not assumed to match you.','Associations can differ by metabolic outcome and population; a common variant does not set carbohydrate limits.'),('biology-2026-10-18.1','placement-rs738409','Ensembl GRCh37 — rs738409 placement and forward alleles','https://grch37.rest.ensembl.org/variation/human/rs738409?content-type=application/json','Genome reference','Population and applicability must be checked in the linked source; not assumed to match you.','Placement and alleles are technical checks, not clinical interpretation. Only the reviewed allele pair is supported.'),('biology-2026-10-18.1','placement-rs58542926','Ensembl GRCh37 — rs58542926 placement and forward alleles','https://grch37.rest.ensembl.org/variation/human/rs58542926?content-type=application/json','Genome reference','Population and applicability must be checked in the linked source; not assumed to match you.','Placement and alleles are technical checks, not clinical interpretation. Only the reviewed allele pair is supported.'),('biology-2026-10-18.1','placement-rs1260326','Ensembl GRCh37 — rs1260326 placement and forward alleles','https://grch37.rest.ensembl.org/variation/human/rs1260326?content-type=application/json','Genome reference','Population and applicability must be checked in the linked source; not assumed to match you.','Placement and alleles are technical checks, not clinical interpretation. Only the reviewed allele pair is supported.'),('biology-2026-10-18.1','mthfr-trial','Crider et al. 2011 — MTHFR, folate and homocysteine supplementation trial','https://pubmed.ncbi.nlm.nih.gov/21508090/','Human intervention','Population and applicability must be checked in the linked source; not assumed to match you.','Biomarker responses in Chinese women; not proof of a genotype-specific disease benefit.'),('biology-2026-10-18.1','mthfr-guidance','CDC — MTHFR and folic acid','https://www.cdc.gov/folic-acid/data-research/mthfr/index.html','Public health guidance','Population and applicability must be checked in the linked source; not assumed to match you.','A common variant does not establish a supplement need or require methylfolate.'),('biology-2026-10-18.1','lactase-study','Leseva et al. 2018 — Lactase genotype, methylation and expression','https://pubmed.ncbi.nlm.nih.gov/29618745/','Human functional association','Population and applicability must be checked in the linked source; not assumed to match you.','Ancestry-dependent marker; symptoms, dose and other persistence variants matter.'),('biology-2026-10-18.1','heart-guidance','AHA 2026 — Dietary guidance for cardiovascular health','https://professional.heart.org/en/science-news/2026-dietary-guidance-to-improve-cardiovascular-health/top-things-to-know','Scientific statement','Population and applicability must be checked in the linked source; not assumed to match you.','Dietary-pattern guidance, not predicted individual treatment effects of these recipes.'),('biology-2026-10-18.1','b12-guidance','NIH ODS — Vitamin B12','https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/','Nutrient evidence review','Population and applicability must be checked in the linked source; not assumed to match you.','Confirm the cause of a low result; replacement route and dose require individual assessment.'),('biology-2026-10-18.1','d-guidance','NIH ODS — Vitamin D','https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/','Nutrient evidence review','Population and applicability must be checked in the linked source; not assumed to match you.','Thresholds vary; excess dosing and medicine interactions require review.'),('biology-2026-10-18.1','iron-guidance','NIH ODS — Iron status and replacement','https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/','Nutrient evidence review','Population and applicability must be checked in the linked source; not assumed to match you.','Ferritin can be affected by inflammation; evaluate the cause and other iron-status markers.'),('biology-2026-10-18.1','fads-study','Polymorphisms in FADS1 and FADS2 alter desaturase activity in young Canadian adults','https://pubmed.ncbi.nlm.nih.gov/21414826/','Human genotype–fatty-acid association','Population and applicability must be checked in the linked source; not assumed to match you.','Association and inferred enzyme activity do not establish a personal omega-3 dose or clinical benefit.'),('biology-2026-10-18.1','tcf-study','TCF7L2 polymorphisms and progression to diabetes in the Diabetes Prevention Program','https://pubmed.ncbi.nlm.nih.gov/16855264/','Genetic analysis within a human intervention trial','Population and applicability must be checked in the linked source; not assumed to match you.','Risk association is not a diagnosis or a validated genotype-specific diet prescription.'),('biology-2026-10-18.1','snp-fads','NCBI dbSNP rs174547','https://www.ncbi.nlm.nih.gov/snp/rs174547','Variant reference','Population and applicability must be checked in the linked source; not assumed to match you.','Placement does not independently confirm the raw call.'),('biology-2026-10-18.1','snp-tcf','NCBI ClinVar — TCF7L2 rs7903146 genomic placement','https://www.ncbi.nlm.nih.gov/clinvar/RCV000007838.2/','Variant reference','Population and applicability must be checked in the linked source; not assumed to match you.','Common susceptibility variant, not a deterministic diagnosis.'),('biology-2026-10-18.1','raw-format','23andMe — Reference genome and strand','https://customercare.23andme.com/hc/en-us/articles/212883767-Which-Reference-Genome-and-Strand-Does-23andMe-Use','Provider technical documentation','Population and applicability must be checked in the linked source; not assumed to match you.','Consumer raw calls are not clinical confirmation.'),('biology-2026-10-18.1','snp-mthfr','NCBI dbSNP rs1801133 — genomic placement','https://www.ncbi.nlm.nih.gov/snp/rs1801133','Variant reference','Population and applicability must be checked in the linked source; not assumed to match you.','A reference placement does not verify an individual''s raw call.'),('biology-2026-10-18.1','snp-lct','NCBI dbSNP rs4988235 — genomic placement','https://www.ncbi.nlm.nih.gov/snp/rs4988235','Variant reference','Population and applicability must be checked in the linked source; not assumed to match you.','Forward genomic alleles differ from gene-oriented C/T notation.'),('biology-2026-10-18.1','oat-viscosity-trial','Wolever et al. 2010 — oat beta-glucan viscosity and LDL','https://pubmed.ncbi.nlm.nih.gov/20660224/','Four-week randomized cereal intervention','Adults with raised LDL; 367 enrolled, 345 completed.','Processing and beta-glucan properties affected response. A bowl''s total fiber does not establish its active beta-glucan dose or your response.'),('biology-2026-10-18.1','usda-composition','USDA — Food and Nutrient Database for Dietary Studies','https://www.ars.usda.gov/nea/bhnrc/fsrg','Food composition reference','Generic food composition, not a clinical trial or your package label.','Preparation and products vary. Qualitative food components do not establish the amount in an unspecified serving.'),('biology-2026-10-18.1','microbiome-consensus','International consensus on microbiome testing (2025 issue)','https://pubmed.ncbi.nlm.nih.gov/39647502/','International expert consensus','Clinical microbiome-testing practice.','Routine consumer microbiome testing has limited demonstrated clinical utility; a reported organism is not a validated treatment target.') ON CONFLICT DO NOTHING;

